/** Native titanium processing/mobility and an independently frozen published ore10 reader. */
public final class TitaniumSmoke {
 public static void verify(ServerLevel level,Path directory)throws Exception{recipes(level);storageAndDrops(level,directory);TitaniumBootsSmoke.verify(level,directory);legacy(level,directory);natural(level,directory);}
 private static void recipes(ServerLevel l){
  var manager=l.getServer().getRecipeManager();for(var item:List.of(TitaniumContent.RAW,TitaniumContent.ORE.asItem(),TitaniumContent.DEEPSLATE_ORE.asItem())){var in=new SingleRecipeInput(new ItemStack(item));require(manager.getRecipeFor(RecipeType.SMELTING,in,l).orElseThrow().value().assemble(in).is(TitaniumContent.INGOT),"native titanium smelting");require(manager.getRecipeFor(RecipeType.BLASTING,in,l).orElseThrow().value().assemble(in).is(TitaniumContent.INGOT),"native titanium blasting");}
  var cells=new ArrayList<ItemStack>();for(int i=0;i<8;i++)cells.add(new ItemStack(TitaniumContent.INGOT));cells.add(new ItemStack(StainlessContent.NICKEL_INGOT));var in=CraftingInput.of(3,3,cells);var out=manager.getRecipeFor(RecipeType.CRAFTING,in,l).orElseThrow().value().assemble(in);require(out.is(TitaniumContent.ALLOY_INGOT)&&out.getCount()==9,"8 titanium + 1 nickel conserves nine ingots");
  for(int i:new int[]{0,8}){var bad=new ArrayList<>(cells);bad.set(i,ItemStack.EMPTY);require(manager.getRecipeFor(RecipeType.CRAFTING,CraftingInput.of(3,3,bad),l).isEmpty(),"alloy requires titanium and nickel");}
  var pack=CraftingInput.of(3,3,java.util.stream.IntStream.range(0,9).mapToObj(i->new ItemStack(TitaniumContent.ALLOY_INGOT)).toList());require(manager.getRecipeFor(RecipeType.CRAFTING,pack,l).orElseThrow().value().assemble(pack).is(TitaniumContent.ALLOY_BLOCK.asItem()),"native alloy storage");var unpack=CraftingInput.of(1,1,List.of(new ItemStack(TitaniumContent.ALLOY_BLOCK)));var ingots=manager.getRecipeFor(RecipeType.CRAFTING,unpack,l).orElseThrow().value().assemble(unpack);require(ingots.is(TitaniumContent.ALLOY_INGOT)&&ingots.getCount()==9,"reversible alloy storage");
 }
 private static void storageAndDrops(ServerLevel l,Path d)throws Exception{
  var pick=new ItemStack(Items.DIAMOND_PICKAXE);var silk=pick.copy();silk.enchant(l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SILK_TOUCH),1);
  for(var ore:List.of(TitaniumContent.ORE,TitaniumContent.DEEPSLATE_ORE)){require(pick.isCorrectToolForDrops(ore.defaultBlockState())&&!new ItemStack(Items.IRON_PICKAXE).isCorrectToolForDrops(ore.defaultBlockState()),"diamond-gated titanium");require(Block.getDrops(ore.defaultBlockState(),l,BlockPos.ZERO,null,null,pick).getFirst().is(TitaniumContent.RAW),"native raw titanium");require(Block.getDrops(ore.defaultBlockState(),l,BlockPos.ZERO,null,null,silk).getFirst().is(ore.asItem()),"native silk titanium");}
  var marker=d.resolve("titanium-storage.txt");boolean prior=Files.exists(marker);int y=prior?Integer.parseInt(Files.readString(marker).trim()):l.getHeight(Heightmap.Types.WORLD_SURFACE,528,0)+4;var pos=new BlockPos(528,y,0);if(!prior){l.setBlock(pos,TitaniumContent.ALLOY_BLOCK.defaultBlockState(),2);Files.writeString(marker,Integer.toString(y));l.getServer().saveEverything(false,true,true);}require(l.getBlockState(pos).is(TitaniumContent.ALLOY_BLOCK),"alloy storage survives relaunch");require(Block.getDrops(l.getBlockState(pos),l,pos,null,null,pick).getFirst().is(TitaniumContent.ALLOY_BLOCK.asItem()),"alloy block self-drop");
 }
 private static void legacy(ServerLevel l,Path d)throws Exception{
  long checked=0;int added=0;java.util.function.Predicate<BlockState> p=s->isTitanium(s);require(!new OreLayer(1,0,0,10,0,0).maybeHas(p)&&new OreLayer(1,0,0,11,0,0).maybeHas(p)&&new OreLayer(1,0,0,11,0,0).affectsPredicate(p),"versioned titanium predicates");
  try(var loader=MetallurgySmoke.historicalReader(Path.of(System.getProperty("blockbranch.oldPlatinumEquipmentClasses")).toUri().toURL())){var old=loader.loadClass("blockbranch.realistic.OreLayer");var ctor=old.getConstructor(long.class,int.class,int.class,int.class,int.class,int.class);var bind=old.getMethod("bind",int.class,int.class);var state=old.getMethod("state",int.class,int.class,int.class,int.class,BlockState.class,boolean.class);
   for(long seed:new long[]{424242,1,-17})for(int cx:new int[]{-1,0,1})for(boolean caves:new boolean[]{false,true}){var frozen=bind.invoke(ctor.newInstance(seed,cx,-1,10,65535,65535),64,64);var retained=new OreLayer(seed,cx,-1,10,65535,65535).bind(64,64);var current=new OreLayer(seed,cx,-1,11,65535,65535).bind(64,64);for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=4;depth<=224;depth+=2){int y=64-depth;var host=(y<0?Blocks.DEEPSLATE:Blocks.STONE).defaultBlockState();var expected=(BlockState)state.invoke(frozen,x,y,z,64,host,caves);require(retained.state(x,y,z,64,host,caves)==expected,"published ore10 exact");var next=current.state(x,y,z,64,host,caves);if(expected!=host)require(next==expected,"titanium cannot replace earlier materials");else if(next!=host){require(isTitanium(next)&&depth>TitaniumVeins.MIN_DEPTH&&depth<TitaniumVeins.MAX_DEPTH,"only titanium in its band added");added++;}checked++;}}
   try{old.getMethod("decode",net.minecraft.nbt.CompoundTag.class).invoke(null,new OreLayer(1,0,0,11,0,0).encode());throw new AssertionError("old reader accepted11");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalArgumentException,"ore10 reader rejects11");}
   var guard=loader.loadClass("blockbranch.cubic.ColumnWorldFormat").getMethod("check",Path.class,boolean.class,boolean.class,boolean.class);for(boolean decoration:new boolean[]{false,true}){var root=Files.createTempDirectory(d,"old-platinum-equipment-");ColumnWorldFormat.check(root,false,decoration,true);var marker=root.resolve("blockbranch-columns.txt");String before=Files.readString(marker);try{guard.invoke(null,root,true,decoration,true);throw new AssertionError("catalog14 accepted15");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalStateException,"prior reader refuses15");}require(Files.readString(marker).equals(before),"prior rejection preserves marker");}
  }
  require(added>0,"titanium witnesses");blockbranch.Blockbranch.LOGGER.info("TITANIUM frozenOre10Comparisons={} added={} oldReaderRejects11=true",checked,added);
 }
 private static void natural(ServerLevel l,Path d)throws Exception{
  if(!(l.getChunkSource().getGenerator() instanceof RealisticGenerator g))return;if(g.oreDefinition()<11){require(g.oreDefinition()>=3&&g.oreDefinition()<=10,"retained prior ore definition");return;}require(g.oreDefinition()>=11,"titanium-compatible definition");var marker=d.resolve("titanium-mined.txt");if(Files.exists(marker)){var v=Files.readString(marker).trim().split(",");var pos=new BlockPos(Integer.parseInt(v[0]),Integer.parseInt(v[1]),Integer.parseInt(v[2]));require(l.getBlockState(pos).isAir()&&isTitanium(((SparseColumn)l.getChunkAt(pos)).blockbranch$terrain().base().state(pos.getX(),pos.getY(),pos.getZ())),"natural titanium edit survives reopen");return;}
  var origin=g.getOrigin(l.getChunkSource().randomState());boolean found=false;search:for(int dz=0;dz<4;dz++)for(int dx=0;dx<4;dx++){var chunk=l.getChunk(origin.x()+dx,origin.z()+dz);var base=((SparseColumn)chunk).blockbranch$terrain().base();require(base.ores().definition()==g.oreDefinition(),"native descriptor11");var restored=TerrainProfile.decode(base.encode(l.palettedContainerFactory()),l.palettedContainerFactory());for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=80;depth<=224;depth++){int y=base.groundHeight(x,z)-depth;var value=base.state(x,y,z);if(!isTitanium(value))continue;var pos=new BlockPos(chunk.getPos().getMinBlockX()+x,y,chunk.getPos().getMinBlockZ()+z);require(l.getBlockState(pos)==value&&restored.state(x,y,z)==value,"native titanium agrees with snapshot");l.setBlock(pos,Blocks.AIR.defaultBlockState(),2);Files.writeString(marker,pos.getX()+","+pos.getY()+","+pos.getZ());l.getServer().saveEverything(false,true,true);blockbranch.Blockbranch.LOGGER.info("TITANIUM natural witness={}",pos);found=true;break search;}}require(found,"bounded titanium witness");
 }
 private static boolean isTitanium(BlockState s){return s.is(TitaniumContent.ORE)||s.is(TitaniumContent.DEEPSLATE_ORE);}
 private static void require(boolean v,String message){if(!v)throw new AssertionError(message);}
 private TitaniumSmoke(){}
}
